/** The API contract, generated by packages/contracts (npm run openapi). The client is built from it. */
val openApiSpec = rootProject.file("../packages/contracts/openapi.json")
val androidSpec = layout.buildDirectory.file("openapi/openapi-android.json")
val generatedClientDir = layout.buildDirectory.dir("generated/openapi")

/**
 * Response schemas are open (`additionalProperties: {}`) so clients tolerate new fields. The
 * Kotlin generator turns those into HashMap subclasses that don't compile, and the app ignores
 * unknown keys when decoding anyway, so this copy drops `additionalProperties` next to `properties`.
 */
val prepareApiSpec = tasks.register("prepareApiSpec") {
    val source = openApiSpec
    val target = androidSpec.get().asFile
    inputs.file(source)
    outputs.file(target)
    doLast {
        @Suppress("UNCHECKED_CAST")
        fun strip(node: Any?) {
            when (node) {
                is MutableMap<*, *> -> {
                    val map = node as MutableMap<String, Any?>
                    if (map.containsKey("properties")) map.remove("additionalProperties")
                    map.values.forEach(::strip)
                }
                is List<*> -> node.forEach(::strip)
            }
        }
        val spec = groovy.json.JsonSlurper().parse(source)
        strip(spec)
        target.apply { parentFile.mkdirs() }.writeText(groovy.json.JsonOutput.toJson(spec))
    }
}

val generateApiClient = tasks.register<GenerateTask>("generateApiClient") {
    dependsOn(prepareApiSpec)
    generatorName.set("kotlin")
    library.set("jvm-retrofit2")
    inputSpec.set(androidSpec)
    outputDir.set(generatedClientDir)
    packageName.set("app.pawsitivemileage.api.generated")
    apiPackage.set("app.pawsitivemileage.api.generated.apis")
    modelPackage.set("app.pawsitivemileage.api.generated.models")
    configOptions.set(
        mapOf(
            "serializationLibrary" to "kotlinx_serialization",
            "useCoroutines" to "true",
            "dateLibrary" to "string",
            "enumPropertyNaming" to "UPPERCASE",
            "omitGradleWrapper" to "true",
            "sourceFolder" to "src/main/kotlin",
        ),
    )
    // Plain Kotlin types: the app needs neither BigDecimal precision nor UUID/URI objects
    typeMappings.set(mapOf("number" to "kotlin.Double", "UUID" to "kotlin.String", "URI" to "kotlin.String"))
    // Only the API and model sources; the app builds its own Retrofit instance and Json
    globalProperties.set(mapOf("apis" to "", "models" to "", "apiTests" to "false", "modelTests" to "false", "apiDocs" to "false", "modelDocs" to "false", "supportingFiles" to "CollectionFormats.kt"))
    validateSpec.set(false) // OpenAPI 3.1; the contracts package validates it with Redocly
}

android {
    namespace = "app.pawsitivemileage"
    compileSdk = 36

    defaultConfig {
        applicationId = "app.pawsitivemileage"
        minSdk = 26
        targetSdk = 36
        versionCode = 1
        versionName = "1.0.0"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    // One flavor per API environment, so a staging build installs next to the production app
    flavorDimensions += "environment"
    productFlavors {
        create("staging") {
            dimension = "environment"
            applicationIdSuffix = ".staging"
            versionNameSuffix = "-staging"
            buildConfigField("String", "API_BASE_URL", "\"https://api-staging.pawsitivemileage.app\"")
            manifestPlaceholders["appAuthRedirectScheme"] = "app.pawsitivemileage.staging"
            resValue("string", "app_name", "PawsitiveMileage (staging)")
        }
        create("production") {
            dimension = "environment"
            buildConfigField("String", "API_BASE_URL", "\"https://api.pawsitivemileage.app\"")
            manifestPlaceholders["appAuthRedirectScheme"] = "app.pawsitivemileage"
            resValue("string", "app_name", "PawsitiveMileage")
        }
    }

    // Release signing from android/keystore.properties (git-ignored; see android/README.md).
    // Without it, release builds are unsigned, which is what CI produces.
    val keystoreProperties = rootProject.file("keystore.properties").takeIf { it.exists() }?.let { file ->
        Properties().apply { file.inputStream().use { load(it) } }
    }
    signingConfigs {
        if (keystoreProperties != null) {
            create("release") {
                storeFile = file(keystoreProperties.getProperty("storeFile"))
                storePassword = keystoreProperties.getProperty("storePassword")
                keyAlias = keystoreProperties.getProperty("keyAlias")
                keyPassword = keystoreProperties.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.findByName("release")
            isMinifyEnabled = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
        }
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    sourceSets["main"].java.srcDir(generatedClientDir.map { it.dir("src/main/kotlin") })

    testOptions.unitTests.isReturnDefaultValues = true
}

kotlin {
    jvmToolchain(17)
}

